def to_jwk(key_obj: str | bytes, as_dict: bool = False) -> Union[JWKDict, str]:
    jwk = {
        "k": base64url_encode(force_bytes(key_obj)).decode(),
        "kty": "oct",
    }

    if as_dict:
        return jwk
    else:
        return json.dumps(jwk)

def from_jwk(jwk: str | JWKDict) -> AllowedRSAKeys:
    try:
        if isinstance(jwk, str):
            obj = json.loads(jwk)
        elif isinstance(jwk, dict):
            obj = jwk
        else:
            raise ValueError
    except ValueError:
        raise InvalidKeyError("Key is not valid JSON")

    if obj.get("kty") != "RSA":
        raise InvalidKeyError("Not an RSA key")

    if "d" in obj and "e" in obj and "n" in obj:
        # Private key
        if "oth" in obj:
            raise InvalidKeyError(
                "Unsupported RSA private key: > 2 primes not supported"
            )

        other_props = ["p", "q", "dp", "dq", "qi"]
        props_found = [prop in obj for prop in other_props]
        any_props_found = any(props_found)

        if any_props_found and not all(props_found):
            raise InvalidKeyError(
                "RSA key must include all parameters if any are present besides d"
            )

        public_numbers = RSAPublicNumbers(
            from_base64url_uint(obj["e"]),
            from_base64url_uint(obj["n"]),
        )

        if any_props_found:
            numbers = RSAPrivateNumbers(
                d=from_base64url_uint(obj["d"]),
                p=from_base64url_uint(obj["p"]),
                q=from_base64url_uint(obj["q"]),
                dmp1=from_base64url_uint(obj["dp"]),
                dmq1=from_base64url_uint(obj["dq"]),
                iqmp=from_base64url_uint(obj["qi"]),
                public_numbers=public_numbers,
            )
        else:
            d = from_base64url_uint(obj["d"])
            p, q = rsa_recover_prime_factors(
                public_numbers.n, d, public_numbers.e
            )

            numbers = RSAPrivateNumbers(
                d=d,
                p=p,
                q=q,
                dmp1=rsa_crt_dmp1(d, p),
                dmq1=rsa_crt_dmq1(d, q),
                iqmp=rsa_crt_iqmp(p, q),
                public_numbers=public_numbers,
            )

        return numbers.private_key()
    elif "n" in obj and "e" in obj:
        # Public key
        return RSAPublicNumbers(
            from_base64url_uint(obj["e"]),
            from_base64url_uint(obj["n"]),
        ).public_key()
    else:
        raise InvalidKeyError("Not a public or private key")

def to_jwk(key: AllowedOKPKeys, as_dict: bool = False) -> Union[JWKDict, str]:
    if isinstance(key, (Ed25519PublicKey, Ed448PublicKey)):
        x = key.public_bytes(
            encoding=Encoding.Raw,
            format=PublicFormat.Raw,
        )
        crv = "Ed25519" if isinstance(key, Ed25519PublicKey) else "Ed448"

        obj = {
            "x": base64url_encode(force_bytes(x)).decode(),
            "kty": "OKP",
            "crv": crv,
        }

        if as_dict:
            return obj
        else:
            return json.dumps(obj)

    if isinstance(key, (Ed25519PrivateKey, Ed448PrivateKey)):
        d = key.private_bytes(
            encoding=Encoding.Raw,
            format=PrivateFormat.Raw,
            encryption_algorithm=NoEncryption(),
        )

        x = key.public_key().public_bytes(
            encoding=Encoding.Raw,
            format=PublicFormat.Raw,
        )

        crv = "Ed25519" if isinstance(key, Ed25519PrivateKey) else "Ed448"
        obj = {
            "x": base64url_encode(force_bytes(x)).decode(),
            "d": base64url_encode(force_bytes(d)).decode(),
            "kty": "OKP",
            "crv": crv,
        }

        if as_dict:
            return obj
        else:
            return json.dumps(obj)

    raise InvalidKeyError("Not a public or private key")

def __init__(self, jwk_data: JWKDict, algorithm: str | None = None) -> None:
    self._algorithms = get_default_algorithms()
    self._jwk_data = jwk_data

    kty = self._jwk_data.get("kty", None)
    if not kty:
        raise InvalidKeyError(f"kty is not found: {self._jwk_data}")

    if not algorithm and isinstance(self._jwk_data, dict):
        algorithm = self._jwk_data.get("alg", None)

    if not algorithm:
        # Determine alg with kty (and crv).
        crv = self._jwk_data.get("crv", None)
        if kty == "EC":
            if crv == "P-256" or not crv:
                algorithm = "ES256"
            elif crv == "P-384":
                algorithm = "ES384"
            elif crv == "P-521":
                algorithm = "ES512"
            elif crv == "secp256k1":
                algorithm = "ES256K"
            else:
                raise InvalidKeyError(f"Unsupported crv: {crv}")
        elif kty == "RSA":
            algorithm = "RS256"
        elif kty == "oct":
            algorithm = "HS256"
        elif kty == "OKP":
            if not crv:
                raise InvalidKeyError(f"crv is not found: {self._jwk_data}")
            if crv == "Ed25519":
                algorithm = "EdDSA"
            else:
                raise InvalidKeyError(f"Unsupported crv: {crv}")
        else:
            raise InvalidKeyError(f"Unsupported kty: {kty}")

    if not has_crypto and algorithm in requires_cryptography:
        raise PyJWKError(f"{algorithm} requires 'cryptography' to be installed.")

    self.Algorithm = self._algorithms.get(algorithm)

    if not self.Algorithm:
        raise PyJWKError(f"Unable to find an algorithm for key: {self._jwk_data}")

    self.key = self.Algorithm.from_jwk(self._jwk_data)

def prepare_key(self, key: str | None) -> None:
    if key == "":
        key = None

    if key is not None:
        raise InvalidKeyError('When alg = "none", key value must be None.')

    return key

def __init__(self, options: dict[str, Any] | None = None) -> None:
    if options is None:
        options = {}
    self.options: dict[str, Any] = {**self._get_default_options(), **options}

def _get_default_options() -> dict[str, bool | list[str]]:
    return {
        "verify_signature": True,
        "verify_exp": True,
        "verify_nbf": True,
        "verify_iat": True,
        "verify_aud": True,
        "verify_iss": True,
        "require": [],
    }

def fetch_data(self) -> Any:
    jwk_set: Any = None
    try:
        r = urllib.request.Request(url=self.uri, headers=self.headers)
        with urllib.request.urlopen(
            r, timeout=self.timeout, context=self.ssl_context
        ) as response:
            jwk_set = json.load(response)
    except (URLError, TimeoutError) as e:
        raise PyJWKClientConnectionError(
            f'Fail to fetch data from the url, err: "{e}"'
        )
    else:
        return jwk_set
    finally:
        if self.jwk_set_cache is not None:
            self.jwk_set_cache.put(jwk_set)

def get_jwk_set(self, refresh: bool = False) -> PyJWKSet:
    data = None
    if self.jwk_set_cache is not None and not refresh:
        data = self.jwk_set_cache.get()

    if data is None:
        data = self.fetch_data()

    if not isinstance(data, dict):
        raise PyJWKClientError("The JWKS endpoint did not return a JSON object")

    return PyJWKSet.from_dict(data)

def __init__(self, keys: list[JWKDict]) -> None:
    self.keys = []

    if not keys:
        raise PyJWKSetError("The JWK Set did not contain any keys")

    if not isinstance(keys, list):
        raise PyJWKSetError("Invalid JWK Set value")

    for key in keys:
        try:
            self.keys.append(PyJWK(key))
        except PyJWTError:
            # skip unusable keys
            continue

    if len(self.keys) == 0:
        raise PyJWKSetError(
            "The JWK Set did not contain any usable keys. Perhaps 'cryptography' is not installed?"
        )

def __init__(self, jwk_set: PyJWKSet):
    self.jwk_set = jwk_set
