def put(self, jwk_set: PyJWKSet) -> None:
    if jwk_set is not None:
        self.jwk_set_with_timestamp = PyJWTSetWithTimestamp(jwk_set)
    else:
        # clear cache
        self.jwk_set_with_timestamp = None

def from_jwk(jwk: str | JWKDict) -> bytes:
